  "steps": [
    {
      "id": 1,
      "claim": "Sociobiology explains behavioral differences in terms of evolutionary selection pressures that affect reproductive success.",
      "evidence": "Standard definition of sociobiology: the study of how natural selection shapes social behaviors that influence fitness.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Epidemiological studies show that paraphilic disorders are diagnosed more frequently in males than in females.",
      "evidence": "DSM‑5 and large‑scale surveys (e.g., Kinsey, National Survey of Sexual Health) consistently report a male‑biased prevalence of paraphilias.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Male reproductive strategy favors a lower threshold for sexual arousal and greater responsiveness to novel sexual stimuli, because males can increase fitness by mating with multiple partners.",
      "evidence": "Evolutionary research on the ‘Coolidge effect’ and sexual selection demonstrates that males of many species, including humans, show heightened interest in novel mates, which is linked to higher reproductive output.",
      "weight": 0.18,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Consequently, sociobiologists argue that the higher male prevalence of paraphilias reflects this evolved tendency to respond to novel sexual cues.",
      "evidence": "Sociobiological literature (e.g., Buss, 1995; Wilson, 1975) interprets atypical sexual interests as an over‑expression of the male‑biased novelty‑seeking sexual system.",
      "weight": 0.21,
      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "Option (B) – “evolutionary selection has favored the development of males who respond to novel sexual stimuli” – precisely captures the sociobiological explanation.",
      "evidence": "The wording of (B) matches the conclusion of step 4.",
      "weight": 0.22,
      "depends_on": [4]
    }
  ],
  "answer": "B",
  "confidence": 0.96,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Paraphilias do not guarantee species survival; many are maladaptive and sociobiology does not claim they are adaptive in that way."
    },
    {
      "answer": "C",
      "reason_rejected": "Left‑right brain differences are a neurological hypothesis, not a sociobiological explanation for sex‑biased prevalence."
    },
    {
      "answer": "D",
      "reason_rejected": "Sociobiology does not assert that male brains are generally “better developed” than female brains; the claim is value‑laden and unsupported."
    }
  ]
